<?php $page_title='Volunteers'; require 'layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';try{if($a==='add'){$uid=(int)$_POST['user_id'];$pdo->prepare('INSERT INTO volunteers(user_id,service_area,skills,verified) VALUES(?,?,?,1) ON DUPLICATE KEY UPDATE service_area=VALUES(service_area),skills=VALUES(skills),verified=1')->execute([$uid,trim($_POST['service_area']),trim($_POST['skills'])]);flash('success','Volunteer added/verified.');}elseif($a==='status'){$pdo->prepare('UPDATE volunteers SET availability=? WHERE id=?')->execute([$_POST['availability'],(int)$_POST['id']]);flash('success','Volunteer availability updated.');}}catch(Throwable $e){flash('error',$e->getMessage());}redirect('volunteers.php');}
$users=$pdo->query("SELECT id,name,email FROM users WHERE role IN ('donor','receiver') ORDER BY name")->fetchAll();$vols=$pdo->query('SELECT v.*,u.name,u.email,u.city FROM volunteers v JOIN users u ON u.id=v.user_id ORDER BY v.created_at DESC')->fetchAll();
?><section class="admin-page-head"><div><span class="kicker">ADMIN / VOLUNTEERS</span><h1>Volunteer Network</h1><p>Verify volunteers, track availability and service areas.</p></div></section><section class="admin-form-card"><h2>Register volunteer</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><label>User<select name="user_id" required><option value="">Choose user</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['name'])?> — <?=e($u['email'])?></option><?php endforeach;?></select></label><label>Service area<input name="service_area" placeholder="Faridabad / Delhi NCR"></label><label>Skills<input name="skills" placeholder="Pickup, driving, coordination"></label><button class="btn primary">Add volunteer</button></form></section><div class="admin-table-card"><div class="table-wrap"><table><thead><tr><th>Volunteer</th><th>Area</th><th>Skills</th><th>Hours</th><th>Verified</th><th>Availability</th></tr></thead><tbody><?php foreach($vols as $v):?><tr><td><b><?=e($v['name'])?></b><small><?=e($v['email'])?></small></td><td><?=e($v['service_area']?:'—')?></td><td><?=e($v['skills']?:'—')?></td><td><?=e($v['hours'])?></td><td><?=((int)$v['verified']?'✓ Yes':'No')?></td><td><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$v['id']?>"><select name="availability"><option>available</option><option>busy</option><option>offline</option></select><button class="mini-btn">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'footer.php'; ?>
